SELECT , u.real_name AS counselor_name
FROM work_reminder w
LEFT JOIN sys_user u ON w.counselor_id = u.id

    AND w.title LIKE CONCAT('%', #{title}, '%')
    AND w.type = #{type}
    AND w.priority = #{priority}
    AND w.status = #{status}
    AND w.counselor_id = #{counselorId}

ORDER BY
    CASE w.priority WHEN '高' THEN 1 WHEN '中' THEN 2 WHEN '低' THEN 3 ELSE 4 END,
    w.due_date ASC,
    w.id DESC

